int memo[12][12][12][12][62];
int capacity[250][250], parent[250];
int distanceMap[20][20], visited[20][20];

inline bool isValid(int x, int y){
	return 0 <= x && x < gridSize && 0 <= y && y < gridSize && gridLabels[x][y] != 'Y' && gridLabels[x][y] != 'Z';
