		int ny = yA + delta[dir];
		if(isValid(nx, ny) && searchPath(nx, ny, xB, yB, step + 1))return res = 1;
	}
	return res = 0;
}

bool bfsFlow(int s, int t){
	memset(parent, -1, sizeof(parent));
	parent[s] = -2;
	queue<int> q;
	q.push(s);
	while(!q.empty()){
		int v = q.front(); q.pop();
		for(int i = s; i <= t; i++){
